func Run() {

	app := app.New()
	app.Settings().SetTheme(theme.LightTheme())
	app.SetIcon(resourceIconPng)

	c := newDashboard()
	c.loadUI(app)
	makeTray(app, c)
	app.Run()
}

func errorWindow(err error, w fyne.Window) {
	dialog.NewError(err, w).Show()
}

func stateDir() string {
	dirname, err := os.UserHomeDir()
	if err != nil {
		log.Fatal(err)
	}

	return filepath.Join(dirname, ".edgevpn")
}

func tailProcess(ctx context.Context, pr *process.Process, c chan string) {

	go func() {
		t, _ := tail.TailFile(pr.StdoutPath(), tail.Config{Follow: true})

		for {
			select {
			case line := <-t.Lines: // Every 100ms increate number of ticks and update UI
				c <- line.Text
			case <-ctx.Done():
				return
			}
		}

	}()
	go func() {
		t, _ := tail.TailFile(pr.StderrPath(), tail.Config{Follow: true})
		for {
			select {
			case line := <-t.Lines: // Every 100ms increate number of ticks and update UI
				c <- line.Text
			case <-ctx.Done():
				return
			}
		}
	}()
}

func newTail(t *widget.Label, w *container.Scroll) chan string {
	s := make(chan string)

	go func() {
		for ss := range s {
			curr := t.Text
			// Prevent too much log to be scrolled
			if len(curr) > 1000 {
				curr = ""
			}
			curr += ss + "\n"
			t.SetText(curr)
			w.ScrollToBottom()
		}
	}()
	return s
}

package gui

import (
	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/driver/desktop"
)

func makeTray(a fyne.App, d *dashboard) {
	visible := true
	if desk, ok := a.(desktop.App); ok {
		menu := fyne.NewMenu("EdgeVPN",
			fyne.NewMenuItem("Show/Hide Dashboard", func() {
				if visible {
					d.window.Hide()
					visible = false
				} else {
					d.window.Show()
					visible = true
				}
			}),
			fyne.NewMenuItem("About", func() {
				about(a)
			}),
		)
		desk.SetSystemTrayMenu(menu)
	}
}

